def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        nanoseconds = int(nanoseconds)
    except ValueError:
        raise ValueError("Invalid nanoseconds value: {}".format(nanoseconds))
    if tz is not None:
        try:
            tz = pytz.timezone(tz)
        except pytz.UnknownTimeZoneError:
            raise ValueError("Invalid time zone: {}".format(tz))
    return Time(nanoseconds, tz)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        return {"days": value.days, "seconds": value.seconds, "microseconds": value.microseconds}
    except AttributeError:
        raise TypeError("Invalid type for dehydration: {}".format(type(value)))

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    try:
        return value.isoformat()
    except AttributeError:
        raise ValueError("Invalid time value")

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Value must be a Point")

    return {
        "x": value.x,
        "y": value.y,
        "z": value.z
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        return list(self.data.keys())
    except AttributeError:
        return []

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._get_handler_class(version) for version in cls._supported_versions}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        handler_class = cls._get_handler_class(protocol_version)
        if handler_class is None:
            raise ValueError(f"Unsupported protocol version: {protocol_version}")
        return {protocol_version: handler_class}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self.keys.index(key)
    except ValueError:
        return -1

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.values())
    else:
        return [self.values()[key] for key in keys]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not keys:
        return self._data

    result = {}
    for key in keys:
        try:
            result[key] = self._data[key]
        except KeyError:
            result[key] = None

    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    try:
        if n == -1:
            n = self.last_query_id
        if qid == -1:
            qid = self.last_query_id
        if dehydration_hooks is None:
            dehydration_hooks = self.dehydration_hooks
        if hydration_hooks is None:
            hydration_hooks = self.hydration_hooks
        if not isinstance(n, int):
            raise TypeError("n must be an integer")
        if not isinstance(qid, int):
            raise TypeError("qid must be an integer")
        if not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        if not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        if not all(isinstance(key, type) for key in dehydration_hooks.keys()):
            raise TypeError("dehydration_hooks keys must be types")
        if not all(isinstance(key, type) for key in hydration_hooks.keys()):
            raise TypeError("hydration_hooks keys must be types")
        if not all(callable(value) for value in dehydration_hooks.values()):
            raise TypeError("dehydration_hooks values must be callable")
        if not all(callable(value) for value in hydration_hooks.values()):
            raise TypeError("hydration_hooks values must be callable")
        if not all(isinstance(handler, type) for handler in handlers.values()):
            raise TypeError("handlers values must be types")
        if not all(issubclass(handler, Response) for handler in handlers.values()):
            raise TypeError("handlers values must be subclasses of Response")
        self.output_queue.append(
            DiscardMessage(n, qid, dehydration_hooks, hydration_hooks, **handlers)
        )
    except Exception as e:
        raise ValueError("Invalid input") from e

def round_half_to_even(n):
    """
    Round a number to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 2 == 0:
        return n
    else:
        return n + 1

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, list):
        raise TypeError("fields must be a list")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    class PointSubclass(Point):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.name = name
            self.fields = fields
            self.srid_map = srid_map

        def __repr__(self):
            return f"{self.name}({', '.join(self.fields)})"

    return PointSubclass

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    # Validate input
    if not isinstance(cmd, tuple) or not all(isinstance(c, str) for c in cmd):
        raise TypeError("cmd must be a tuple of strings")
    if not isinstance(varargs, Sequence) or not all(isinstance(v, str) for v in varargs):
        raise TypeError("varargs must be a sequence of strings")
    if not isinstance(color, bool):
        raise TypeError("color must be a boolean")
    if not isinstance(target_concurrency, int) or target_concurrency < 1:
        raise ValueError("target_concurrency must be a positive integer")
    if not isinstance(_max_length, int) or _max_length < 1:
        raise ValueError("_max_length must be a positive integer")

    # Initialize variables
    partitions = []
    partition_size = len(varargs) // target_concurrency
    remainder = len(varargs) % target_concurrency

    # Create partitions
    for i in range(target_concurrency):
        start = i * partition_size
        end = start + partition_size
        if i < remainder:
            end += 1
        partitions.append(varargs[start:end])

    # Run commands in parallel
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_partition = {executor.submit(run_command, cmd, partition, color, _max_length, **kwargs): partition for partition in partitions}
        for future in concurrent.futures.as_completed(future_to_partition):
            partition = future_to_partition[future]
            try:
                results.append((future.result(), partition))
            except Exception as e:
                results.append((e, partition))

    # Return results
    return tuple(results)

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    try:
        return list(seq)
    except TypeError:
        raise ValueError("Invalid input type, must be a sequence of strings") from None
    except Exception as e:
        raise RuntimeError("Unexpected error occurred during shuffling") from e

def parse_version(s: str) -> tuple[int, ...]:
    """
    Poor man's version comparison

    :param s: The version string to parse
    :return: A tuple of integers representing the version number
    """
    try:
        return tuple(int(x) for x in s.split('.'))
    except ValueError:
        raise ValueError(f"Invalid version string: {s}")

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def wrapper(func):
        cache = {}
        def wrapped(*args, **kwargs):
            if typed:
                key = (args, tuple(kwargs.items()))
            else:
                key = (args, tuple(kwargs.values()))
            if key in cache:
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result
        return wrapped
    return wrapper

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def wrapper(func):
        cache = {}
        def inner(*args, **kwargs):
            if typed:
                key = args + tuple(kwargs.items())
            else:
                key = args
            if key in cache:
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result
        return inner
    return wrapper

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def wrapper(func):
        cache = {}
        def _wrapper(*args, **kwargs):
            if typed:
                key = _make_key(args, kwargs, typed)
            else:
                key = _make_key(args, kwargs)
            if key in cache:
                cache[key] += 1
            else:
                cache[key] = 1
                result = func(*args, **kwargs)
                cache[key] = result
            return cache[key]
        return _wrapper
    return wrapper

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        return self.get(key, default)
    except KeyError:
        self[key] = default
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def append_text_to_file(file_name, text_buffer, encoding, overwrite=False):
    try:
        with open(file_name, 'a' if not overwrite else 'w', encoding=encoding) as f:
            f.write(text_buffer)
        return len(text_buffer)
    except OSError as e:
        return -1

def file_to_textbuffer(file_name, encoding):
    try:
        with open(file_name, 'r', encoding=encoding) as f:
            return f.read()
    except FileNotFoundError:
        return None
    except UnicodeDecodeError:
        return None

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        return self.__class__.__name__.replace('Py', '').replace('Fallback', '')
    except Exception as e:
        raise ValueError(f"Invalid class name: {self.__class__.__name__}") from e

def _legacy_mergeOrderings(orderings):
    result = []
    for ordering in orderings:
        for item in ordering:
            if item not in result:
                result.append(item)
    return result

def directlyProvidedBy(object):
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        return object.getInterfaces()
    except AttributeError:
        raise TypeError("object does not have a getInterfaces() method") from None
