def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface."""
    try:
        if all:
            return self.getAllAttributes()
        else:
            return self.getAttributes()
    except Exception as e:
        raise ValueError("Error getting attribute names and descriptions") from e

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    try:
        if all:
            return list(self.__dict__.keys())
        else:
            return [key for key in self.__dict__.keys() if not key.startswith('_')]
    except AttributeError:
        return []

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, Declaration):
            output.append(item)
        elif isinstance(item, tuple):
            output.extend(item)
        else:
            raise ValueError("Invalid argument type")
    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import platform
        if platform.python_implementation() == "PyPy":
            return False
        if os.environ.get("PURE_PYTHON", "0") == "1":
            return False
        return True
    except Exception as e:
        return False

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if self.initial_value is not None:
        self.bins = [self.initial_value] * self.num_bins
    else:
        self.bins = self.make_bins()

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if len(bins) != len(edges) - 1:
        raise ValueError("Number of bins and edges must be equal.")
    if not all(isinstance(x, (int, float)) for x in bins):
        raise ValueError("Bins must be numeric.")
    if not all(isinstance(x, (int, float)) for x in edges):
        raise ValueError("Edges must be numeric.")
    if not all(edges[i] < edges[i+1] for i in range(len(edges)-1)):
        raise ValueError("Edges must be in increasing order.")

    total = 0
    for i in range(len(bins)):
        total += bins[i] * (edges[i+1] - edges[i])
    return total

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        if hasattr(obj, 'fill') and hasattr(obj, 'request'):
            return True
        else:
            return False
    except:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, "run"))
    except AttributeError:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        if not hasattr(obj, 'fill') or not hasattr(obj, 'compute'):
            return False
        if not callable(obj.fill) or not callable(obj.compute):
            return False
        return True
    except:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return d1
    diff = {}
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
        elif isinstance(value, dict):
            subdiff = difference(value, d2[key], level-1)
            if subdiff:
                diff[key] = subdiff
    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("Coordinate must be a tuple of length 2")
    if not isinstance(weight, (int, float)):
        raise ValueError("Weight must be a number")
    if weight < 0:
        raise ValueError("Weight must be non-negative")

    x, y = coord
    if x < 0 or x >= self.width or y < 0 or y >= self.height:
        return

    self.data[y][x] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    from typing import Dict, List

    def _validate_label(key, value):
        if not isinstance(key, str):
            raise ValidationError(f"Label key '{key}' does not match the regex [...]")
        if not isinstance(value, str):
            raise ValidationError(f"Label value '{value}' does not match the regex [...]")
        if not re.match(r"^[a-zA-Z0-9_]+$", key):
            raise ValidationError(f"Label key '{key}' does not match the regex [...]")
        if not re.match(r"^[a-zA-Z0-9_]+$", value):
            raise ValidationError(f"Label value '{value}' does not match the regex [...]")

    errors = []
    for key, value in labels.items():
        try:
            _validate_label(key, value)
        except ValidationError as err:
            errors.append({key: err.message})

    if errors:
        raise ValidationError(errors)

def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    try:
        return re.compile(r"^[a-z0-9]([-a-z0-9]*[a-z0-9])?$")
    except re.error as e:
        raise ValueError("Invalid regular expression") from e

def validate_key(key):
    import re
    pattern = r"^[a-zA-Z0-9_-]{3,20}$"
    if not re.match(pattern, key):
        raise ValidationError("Invalid key: {}".format(key))
    return key

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        elif isinstance(last_applied_manifest[field], list):
            update_last_applied_manifest_list_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
        elif isinstance(last_applied_manifest[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema:
        if field not in response:
            raise KeyError(f"Observed field '{field}' not present in Kubernetes response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        manifest = app.spec.manifest
        for resource in manifest:
            if not resource.observer_schema:
                resource.observer_schema = generate_default_observer_schema_for_resource(resource)
    except AttributeError:
        raise ValueError("Invalid application object")
    return app

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
        :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(params, (Mapping, Sequence)):
        raise TypeError("params must be a Mapping or Sequence")

    if isinstance(params, Mapping):
        in_style = self.in_style
        if in_style == "named":
            out_style = "named"
        elif in_style == "pyformat":
            out_style = "pyformat"
        elif in_style == "format":
            out_style = "format"
        else:
            raise ValueError("Unsupported in_style")

        if out_style == "named":
            out_params = {key: value for key, value in params.items()}
        elif out_style == "pyformat":
            out_params = {key: value for key, value in params.items()}
        elif out_style == "format":
            out_params = [value for key, value in params.items()]
        else:
            raise ValueError("Unsupported out_style")
    else:
        out_params = params

    return sql, out_params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Check if the path is a valid OCFL object
        if not self.is_ocfl_object(path):
            return False

        # Check if the OCFL object is valid
        if not self.is_valid_ocfl_object(path):
            return False

        # Check if the OCFL object has any warnings
        if self.has_warnings(path):
            return False

        return True
    except Exception as e:
        # If there is an error, return False
        return False

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = self.status()
        if status == 'valid':
            return f'{prefix}Valid'
        elif status == 'invalid':
            return f'{prefix}Invalid'
        else:
            return f'{prefix}Unknown'
