def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    try:
        for manifest_file in manifest_files:
            if manifest_file.digest not in digests_used:
                raise ValueError(f"Digest {manifest_file.digest} is not used in the manifest.")
        return True
    except ValueError as e:
        print(e)
        return False

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")

    if prior.inventory_id != self.inventory_id:
        raise ValueError("prior inventory ID does not match current inventory ID")

    if prior.version >= self.version:
        raise ValueError("prior inventory version must be less than current inventory version")

    # Check that all items in prior inventory are also in current inventory
    for item in prior.items:
        if item not in self.items:
            raise ValueError(f"item {item} is not in current inventory")

    # Check that all items in current inventory have the same quantity as in prior inventory
    for item in self.items:
        if item not in prior.items:
            raise ValueError(f"item {item} is not in prior inventory")
        if prior.items[item] != self.items[item]:
            raise ValueError(f"quantity of item {item} does not match between prior and current inventory")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for file in inventory:
        if file.version == version:
            logical_path = file.logical_path
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(file)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for file_path, fixity_info in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} is not listed in the manifest")

        if not isinstance(fixity_info, dict):
            raise ValueError(f"Fixity information for file {file_path} must be a dictionary")

        for fixity_type, fixity_value in fixity_info.items():
            if fixity_type not in ["md5", "sha1", "sha256"]:
                raise ValueError(f"Invalid fixity type {fixity_type} for file {file_path}")

            if not isinstance(fixity_value, str):
                raise ValueError(f"Fixity value for file {file_path} must be a string")

            if len(fixity_value) != 32:
                raise ValueError(f"Fixity value for file {file_path} must be a 32-character string")

    return True

