def render(pieces, style):
    """
    Render the given version pieces into the requested style.

    :param pieces: The version pieces to render.
    :param style: The style to render the version in.
    :return: The rendered version string.
    """
    # Validate the input
    if not isinstance(pieces, list):
        raise TypeError("pieces must be a list")
    if not isinstance(style, str):
        raise TypeError("style must be a string")

    # Render the version
    if style == "semver":
        return ".".join(str(piece) for piece in pieces)
    elif style == "pep440":
        return ".".join(str(piece) for piece in pieces) + "-" + ".".join(str(piece) for piece in pieces)
    else:
        raise ValueError("Invalid style")

def plus_or_dot(pieces):
