def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("No commands specified")
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string")
    if env is not None and not isinstance(env, dict):
        raise ValueError("env must be a dictionary")
    if not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")

    for command in commands:
        if not isinstance(command, str):
            raise ValueError("command must be a string")
        if not command:
            raise ValueError("command cannot be empty")

    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("arg must be a string")
        if not arg:
            raise ValueError("arg cannot be empty")

    if cwd is not None:
        os.chdir(cwd)

    if env is not None:
        for key, value in env.items():
            os.environ[key] = value

    if verbose:
        print("Running command:", " ".join(commands))

    try:
        result = subprocess.run(commands, args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if hide_stderr:
            result.stderr = b""
        return result.stdout.decode("utf-8")
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Command failed with exit code {}: {}".format(e.returncode, " ".join(commands))) from e

def register_vcs_handler(vcs, method):
