def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if not all(isinstance(x, str) for x in alphabet):
        raise TypeError("alphabet must contain only strings")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer")

    if number == 0:
        return alphabet[0]

    result = ""
    base = len(alphabet)
    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("value must be a string")
    if not isinstance(arg, str):
        raise ValueError("arg must be a string")
    return value.replace(".", arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string or not alphabet:
        raise ValueError("Input string and alphabet must not be empty")
    if not all(c in alphabet for c in string):
        raise ValueError("Input string contains invalid characters")
    if len(alphabet) < 2:
        raise ValueError("Alphabet must have at least 2 characters")

    base = len(alphabet)
    num = 0
    for i, c in enumerate(string):
        num += alphabet.index(c) * (base ** i)

    return num

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("Name must be a string")
    if name.startswith('"') and name.endswith('"'):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = sys.platform
    if platform == 'win32':
        return _split_windows(s)
    else:
        return _split_posix(s)

def addignored(ignored):
    try:
        result = subprocess.check_output(['git', 'status', '--ignored', '--porcelain'])
        ignored_files = [line.split()[-1] for line in result.decode('utf-8').splitlines() if line.startswith('!! ')]
        return ', '.join(ignored_files)
    except subprocess.CalledProcessError as e:
        raise RuntimeError('Error executing git command') from e

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None
    try:
        num, unit = frequency.split()
        num = int(num)
        if unit == "day" or unit == "days":
            return datetime.timedelta(days=num)
        elif unit == "week" or unit == "weeks":
            return datetime.timedelta(weeks=num)
        elif unit == "month" or unit == "months":
            return datetime.timedelta(days=num * 30)
        elif unit == "year" or unit == "years":
            return datetime.timedelta(days=num * 365)
        else:
            raise ValueError(f"Invalid unit of time: {unit}")
    except ValueError:
        raise ValueError(f"Invalid frequency: {frequency}")

def is_local(host):
    try:
        ip_address = socket.gethostbyname(host)
        return ip_address == "127.0.0.1"
    except socket.gaierror:
        return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        if os.name == "nt" and "GIT_BASH" in os.environ:
            return True
        else:
            return False
    except Exception as e:
        print(f"Error occurred while checking if running in gitbash: {e}")
        return False

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("Pattern must be a string")
    if strip:
        pattern = pattern.strip()
    try:
        return re.compile(pattern)
    except re.error:
        raise ValueError("Invalid regex pattern")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if isinstance(commands, str):
            commands = [commands]
        for command in commands:
            if cwd is not None:
                os.chdir(cwd)
            if env is not None:
                os.environ.update(env)
            if verbose:
                print(f"Running command: {command}")
            result = subprocess.run(command, args, capture_output=True, text=True)
            if hide_stderr:
                result.stderr = ""
            if verbose:
                print(f"Command output: {result.stdout}")
            if result.returncode != 0:
                raise RuntimeError(f"Command {command} failed with exit code {result.returncode}")
        return result.stdout
    except Exception as e:
        raise RuntimeError(f"Error running command: {e}")

