def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2) ** 2) / (2 * (0.1 ** 2)))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []
    for config_filename in config_filenames:
        try:
            with open(config_filename) as f:
                config = json.load(f)
                if overrides:
                    config = {**config, **overrides}
                if resolve_env:
                    config = _resolve_env_vars(config)
                configs[config_filename] = config
        except FileNotFoundError:
            errors.append(logging.LogRecord(logging.ERROR, "Configuration file not found: {}".format(config_filename)))
        except json.JSONDecodeError:
            errors.append(logging.LogRecord(logging.ERROR, "Configuration file is not valid JSON: {}".format(config_filename)))
        except Exception as e:
            errors.append(logging.LogRecord(logging.ERROR, "Unexpected error while loading configuration file: {}".format(config_filename)))
    return configs, errors

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._get_handler_class(version) for version in cls._supported_versions}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        handler_class = cls._get_handler_class(protocol_version)
        if handler_class is None:
            raise ValueError(f"Unsupported protocol version: {protocol_version}")
        return {protocol_version: handler_class}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    bookmarks = []
    for value in values:
        try:
            bookmark = Bookmark.from_raw_value(value)
            bookmarks.append(bookmark)
        except ValueError:
            pass
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    if not isinstance(seq, collections.abc.Sequence):
        raise TypeError("seq must be a sequence type")
    if bufsize is not None and not isinstance(bufsize, int):
        raise TypeError("bufsize must be an integer")
    if bufsize is not None and bufsize < 0:
        raise ValueError("bufsize must be non-negative")
    if isinstance(seq, str):
        return (seq, "str")
    elif isinstance(seq, bytes):
        return (seq, "bytes")
    else:
        return (list(seq), "list")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a type")
    if not issubclass(candidate, iface):
        raise TypeError("candidate must be a subclass of iface")
    if tentative and not issubclass(candidate, iface):
        raise TypeError("candidate must be a subclass of iface")
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set()
    for base in bases:
        if hasattr(base, '__class__'):
            metaclasses.add(base.__class__)
    if len(metaclasses) == 1:
        return metaclasses.pop()
    else:
        raise TypeError("Inconsistent metaclasses found")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:
        if default is not __marker:
            return default
        else:
            raise

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    min_count = float("inf")
    min_key = None
    for key, (value, count) in self.items():
        if count < min_count:
            min_count = count
            min_key = key

    if min_key is None:
        raise KeyError("popitem(): dictionary is empty")

    value = self[min_key]
    del self[min_key]
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    oldest_key = None
    for key, _ in self.items():
        if oldest_key is None or self._order[key] < self._order[oldest_key]:
            oldest_key = key

    value = self[oldest_key]
    del self[oldest_key]
    return (oldest_key, value)

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        return re.compile(r"^in\s*:\s*\((.*)\)\s*$", re.IGNORECASE)
    except re.error as e:
        raise ValueError("Invalid in-style parameter regular expression") from e

def _create_converter(self) -> _converting._Converter:
    """
