        return converter
    except Exception as e:
        raise e

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request.public_message:
            return True
        elif request.private_message:
            return True
        elif request.legacy_payload:
            return True
        else:
            return False
    except Exception as e:
        print(f"Error identifying request: {e}")
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request.headers["Content-Type"] == "application/json":
            data = json.loads(request.body)
            if data["type"] == "matrix":
                return True
        return False
    except (KeyError, ValueError):
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    try:
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except AttributeError:
        raise ValueError("Invalid datetime object") from None

def find_tags(text, replacer=None):
    """
    Find tags in text and return a set of tags and the original or replaced text.
    """
    tags = set()
    code_block = False
    for word in text.split():
        if word == "```":
            code_block = not code_block
        elif not code_block and word.startswith("#"):
            tags.add(word[1:])
            if replacer is not None:
                word = replacer(word[1:])
    return tags, text.replace(word, replacer(word[1:]))

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        return response.headers.get("Content-Type")
    except requests.exceptions.RequestException:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("Tag must be a string")
    if len(tag) < 3:
        raise ValueError("Tag must be at least 3 characters long")
    if not tag.isalnum():
        raise ValueError("Tag must contain only letters and digits")
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if not isinstance(node, xml.etree.ElementTree.Element):
        raise ValueError("node must be an ElementTree Element")

    children = node.getchildren()
    result = {}
    for child in children:
        tag = child.tag
        if tag in result:
            raise ValueError(f"Duplicate tag {tag} found in children of node {node}")
        result[tag] = child

    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    try:
        if not url.startswith("http"):
            raise ValueError("Invalid URL: must start with 'http'")
        if document_path and not document_path.startswith("/"):
            raise ValueError("Invalid document path: must start with '/'")
        nodeinfo_url = url + (document_path or "/.well-known/nodeinfo")
        response = requests.get(nodeinfo_url)
        if response.status_code != 200:
            raise ValueError("Invalid response: status code must be 200")
        return response.json()
    except ValueError as e:
        raise ValueError("Invalid input: " + str(e))
    except requests.exceptions.RequestException as e:
        raise ValueError("Error fetching NodeInfo document: " + str(e))

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return {
            "subject": data["subject"],
            "aliases": data["aliases"],
            "links": data["links"],
            "properties": data["properties"]
        }
    except json.JSONDecodeError:
        pass

    try:
        xrd = XRD.parse(document)
        return {
            "subject": xrd.subject,
            "aliases": xrd.aliases,
            "links": xrd.links,
            "properties": xrd.properties
        }
    except XRD.ParseError:
        raise ValueError("Invalid Diaspora webfinger document") from None

    raise ValueError("Invalid Diaspora webfinger document")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException:
        return None

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        response = requests.get(f"https://{host}/.well-known/host-meta.json")
        response.raise_for_status()
        return XRD.from_json(response.json())
    except requests.exceptions.RequestException as e:
        raise DiasporaError(f"Failed to retrieve host-meta from {host}") from e

def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    :param dic: The dictionary to insert the value into.
    :param val: The value to insert.
    :param key: The first key in the chain of keys that will store the value.
    :param keys: The sub keys in the key chain.
    :raises TypeError: If the dictionary is not a dictionary.
    :raises TypeError: If the key is not a string.
    """
    if not isinstance(dic, dict):
        raise TypeError("Dictionary must be a dictionary")
    if not isinstance(key, str):
        raise TypeError("Key must be a string")
    if keys:
        if key not in dic:
            dic[key] = {}
        dict_insert(dic[key], val, *keys)
    else:
        dic[key] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Validate input
    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    # Initialize empty list to store file names
    file_names = []

    # Iterate over settings directories
    for settings_dir in settings_dirs:
        # Check if settings directory exists
        if not os.path.exists(settings_dir):
            continue

        # Iterate over files in settings directory
        for file in os.listdir(settings_dir):
            # Check if file is a regular file
            if not os.path.isfile(os.path.join(settings_dir, file)):
                continue

            # Check if file name matches spec option
            if spec_option in file:
                file_names.append(file)

    return file_names

