def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    try:
        spec_dict = yaml.safe_load(spec_content)
        required_fields = ['name', 'version', 'description', 'author', 'email']
        for field in required_fields:
            if field not in spec_dict:
                raise IRValidatorException(f"Missing required field '{field}' in spec file")
        return spec_dict
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML content: {e}")

def validate_from_file(yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file, 'r') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError:
        raise IRValidatorException(f"YAML file not found: {yaml_file}")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {e}")

    # Validate that all required fields are present
    required_fields = ['name', 'description', 'version', 'author', 'email']
    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Missing required field: {field}")

    return data

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    try:
        deprecated_args = {}
        for arg in self.args:
            if arg.deprecated:
                deprecated_args[arg.name] = arg.deprecated
        return deprecated_args
    except Exception as e:
        raise ValueError("Error getting deprecated args") from e

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check if the argument is deprecated
    for arg in cli_args:
        if arg in self.deprecated_args:
            print(f"WARNING: The argument '{arg}' is deprecated and will be removed in a future version.")

    # Check if the argument is deprecated in the answer file
    for arg in answer_file_args:
        if arg in self.deprecated_args:
            print(f"WARNING: The argument '{arg}' is deprecated and will be removed in a future version.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        command = self.get_command(command_name)
        return command.option_specs
    except KeyError:
        raise ValueError(f"Invalid command name: {command_name}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    for option in options_spec:
        if option.get("required_when"):
            required_when_conditions = option["required_when"]
            for condition in required_when_conditions:
                if self._check_condition(command_name, condition, args):
                    required_args.append(option["name"])
                    break
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than the maximum length of {self.length}")
    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg not in self.choices:
            raise ValueError(f"Invalid choice: {arg}. Must be one of {self.choices}")
    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check if the number of arguments is valid
    if len(args) != 2:
        raise ValueError("Invalid number of arguments. Expected 2, received {}.".format(len(args)))

    # Check if the arguments are of the correct type
    if not isinstance(args[0], int) or not isinstance(args[1], int):
        raise TypeError("Invalid argument type. Expected int, received {} and {}.".format(type(args[0]), type(args[1])))

    # Check if the first argument is less than or equal to the second argument
    if args[0] > args[1]:
        raise ValueError("Invalid argument value. The first argument must be less than or equal to the second argument.")

def get_nested_custom_and_control_args(self, args):
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    for key, value in extra_vars.items():
        if key not in vars_dict:
            vars_dict[key] = value
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    try:
        # Validate input parameters
        if not isinstance(ir_workspace, InfraredWorkspace):
            raise ValueError("ir_workspace must be an InfraredWorkspace object")
        if not isinstance(ir_plugin, InfraredPlugin):
            raise ValueError("ir_plugin must be an InfraredPlugin object")
        if not isinstance(playbook_path, str):
            raise ValueError("playbook_path must be a string")
        if verbose is not None and not isinstance(verbose, int):
            raise ValueError("verbose must be an integer")
        if extra_vars is not None and not isinstance(extra_vars, dict):
            raise ValueError("extra_vars must be a dict")
        if ansible_args is not None and not isinstance(ansible_args, dict):
            raise ValueError("ansible_args must be a dict")

        # Build the ansible-playbook command
        command = ["ansible-playbook", playbook_path]
        if verbose is not None:
            command.append("-" + str(verbose))
        if extra_vars is not None:
            for key, value in extra_vars.items():
                command.append("-e")
                command.append(f"{key}={value}")
        if ansible_args is not None:
            for key, value in ansible_args.items():
                command.append(f"--{key}")
                command.append(value)

        # Run the command
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Return the result
        return result.stdout.decode("utf-8")
    except Exception as e:
        raise RuntimeError(f"Error running ansible-playbook: {e}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    try:
        for key, value in values_dict.items():
            if key in self.arg_types[parser_name]:
                values_dict[key] = self.arg_types[parser_name][key](value)
    except KeyError:
        pass
    except ValueError:
        raise ValueError(f"Invalid value for argument '{key}': {value}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(os.path.join(plugin_dir, "plugin.spec"), "r") as f:
            spec = yaml.safe_load(f)
            flatten_dict = {}
            for key, value in spec.items():
                if isinstance(value, dict):
                    for subkey, subvalue in value.items():
                        flatten_dict[f"{key}.{subkey}"] = subvalue
                else:
                    flatten_dict[key] = value
            return flatten_dict
    except FileNotFoundError:
        raise ValueError(f"Plugin spec file not found in {plugin_dir}")
    except yaml.YAMLError:
        raise ValueError(f"Invalid YAML format in plugin spec file {plugin_dir}")

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get("CONFIG_PATH"):
        os.environ["CONFIG_PATH"] = "/path/to/config.ini"
    return os.environ["CONFIG_PATH"]

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return path[len(root):]
